import{z as B,x as l,o as E,c as i,q as s,j as n,D as e,d as o,s as r,S as A}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"强扩展与弱扩展","description":"","frontmatter":{"title":"强扩展与弱扩展","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/strong-weak-scaling.md","filePath":"cs/strong-weak-scaling.md","lastUpdated":1791063341000}'),c={name:"cs/strong-weak-scaling.md"};function d(p,a,C,m,_,h){const t=l("Mermaid");return E(),i("div",null,[a[2]||(a[2]=s('<h1 id="强扩展与弱扩展" tabindex="-1">强扩展与弱扩展 <a class="header-anchor" href="#强扩展与弱扩展" aria-label="Permalink to &quot;强扩展与弱扩展&quot;">​</a></h1><div class="epigraph"><p>强扩展：问题不动，加核看时间掉不掉；弱扩展：每核工作量大致不变，看效率能不能稳住。两条曲线回答的不是同一个问题。</p><footer>—— 据并行计算实践与 Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/gustafson-law">上一课</a> 区分了两种规模假设。实验室和论文里要用成对术语，避免只丢「加速比 16×」却不说输入。本课不重推公式。缺口是 <strong>强扩展 vs 弱扩展的实验设计，以及 NoC/NUMA 如何让曲线弯折。</strong></p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>只报强扩展：大核数上 <a href="/cs/cpi-amdahl">阿姆达尔</a> 加上 <a href="/cs/directory-scalability">目录热点</a> 让曲线塌掉，于是有人说「并行无用」。只报弱扩展：问题变大，cache 工作集、通信体积都变，效率看起来很好，用户的单个实例并未变快。缺口不是新定律，而是<strong>两套曲线都要，并写清每核工作量。</strong></p><p><span class="marginnote">两个词翻成白话：强扩展问「人多了，同一件事能不能更快」；弱扩展问「人多了，每人干的活不变，总产量能不能成比例涨」。同名的「效率」在两种实验里分子分母都不同，混报等于没报。</span></p><p><span class="marginnote">效率 \\(E = T_1 / (n T_n)\\)（强）或相对单核同等每核工作量。通信/计算比随强扩展变差（表面积/体积），弱扩展下更稳定。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>强：固定 \\(N\\)，画 \\(T(n)\\)。弱：固定每核点数，画 \\(T(n)\\) 是否平坦。同时记录：跨 <a href="/cs/multi-socket-interconnect">socket</a> 比例、LLC miss、NoC 拥塞计数（下一课 PMU）。</p><p><span class="marginnote">数字实例：固定 1e8 个元素，1 核跑 100 秒、16 核跑 10 秒，强扩展效率是 100 除以 (16×10)，约 62.5%；弱扩展则改成每核 1e8 个——16 核的输入是 1.6e9，若时间仍约 100 秒，弱效率接近 100%。两组数字讲的不是一件事。</span></p>',10)),(E(),n(A,null,{default:e(()=>[r(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20STR%5B%22%E5%BC%BA%E6%89%A9%E5%B1%95%EF%BC%9AN%20%E5%9B%BA%E5%AE%9A%22%5D%20--%3E%20AMD%5B%22%E9%80%BC%E8%BF%91%20Amdahl%20%2B%20%E4%BA%89%E7%94%A8%22%5D%0A%20%20WEAK%5B%22%E5%BC%B1%E6%89%A9%E5%B1%95%EF%BC%9A%E6%AF%8F%E6%A0%B8%E5%B7%A5%E4%BD%9C%E9%87%8F%E5%9B%BA%E5%AE%9A%22%5D%20--%3E%20GUS%5B%22%E9%80%BC%E8%BF%91%20Gustafson%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=s('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>强扩展把通信摊到更少的本地工作上，<a href="/cs/memory-coalescing">合并</a> 与 halo 交换相对变贵。弱扩展保持算术强度，更接近 <a href="/cs/roofline-model">Roofline</a> 的带宽上限是否随节点线性涨。GPU 上「加 SM」类似弱扩展若每个 SM 仍吃一块固定 tile。</p><p>跨 <a href="/cs/multi-socket-interconnect">socket</a> 时两条曲线都会提前弯折：强扩展把远程 miss 占比拉高，弱扩展若每核工作集仍拟合本地 DRAM 则还能看。报告里应附每核工作集与 NUMA 命中比例，否则「效率 90%」无法复核。</p>',3)),(E(),n(A,null,{default:e(()=>[r(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20EXP%5B%22%E6%8B%BF%E5%88%B0%E4%B8%80%E7%BB%84%E6%89%A9%E5%B1%95%E5%AE%9E%E9%AA%8C%E6%95%B0%E6%8D%AE%22%5D%20--%3E%20Q%7B%22%E5%85%88%E9%97%AE%EF%BC%9A%E6%B5%8B%E7%9A%84%E6%98%AF%E5%93%AA%E7%A7%8D%EF%BC%9F%22%7D%0A%20%20Q%20--%3E%7C%22%E5%BC%BA%EF%BC%9AN%20%E5%9B%BA%E5%AE%9A%EF%BC%8C%E5%8A%A0%E6%A0%B8%22%7C%20S1%5B%22%E7%9C%8B%E6%97%B6%E9%97%B4%E6%8E%89%E5%BE%97%E5%A4%9A%E5%BF%AB%22%5D%0A%20%20S1%20--%3E%20S2%5B%22%E5%9D%8F%E4%BF%A1%E5%8F%B7%EF%BC%9A%E8%BF%9C%E7%A8%8B%20miss%20%E5%8D%A0%E6%AF%94%E5%8D%87%E9%AB%98%E3%80%81%E6%9B%B2%E7%BA%BF%E5%A1%8C%22%5D%0A%20%20Q%20--%3E%7C%22%E5%BC%B1%EF%BC%9A%E6%AF%8F%E6%A0%B8%E5%B7%A5%E4%BD%9C%E9%87%8F%E5%9B%BA%E5%AE%9A%22%7C%20W1%5B%22%E7%9C%8B%E6%95%88%E7%8E%87%E7%A8%B3%E4%B8%8D%E7%A8%B3%22%5D%0A%20%20W1%20--%3E%20W2%5B%22%E5%9D%8F%E4%BF%A1%E5%8F%B7%EF%BC%9A%E6%AF%8F%E6%A0%B8%E5%B7%A5%E4%BD%9C%E9%9B%86%E6%92%91%E7%88%86%E6%9C%AC%E5%9C%B0%20DRAM%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=s('<p><span class="marginnote">常见误区：拿强扩展的塌陷断言「并行无用」，或拿弱扩展的平坦断言「扩展性极好」——前者回答「单个实例能快到哪」，后者回答「吞吐能涨到哪」，两条曲线合在一起才构成判断。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不规定必须用哪种 MPI 模式。SPEC 下一课：许多 CPU 基准是固定输入的强扩展（其实单进程），并行套件另说。陷阱在输入与编译选项。</p><p>后课默认：扩展曲线要标明强/弱。读 SPEC 分数前先问：测的是哪套输入、是否允许自动并行。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>强扩展固定问题；弱扩展固定每核工作量。</li><li>通信比随强扩展恶化更明显。</li><li>SPEC 等基准的陷阱是下一课。</li><li>出处：Gustafson；Hennessy and Patterson, <em>CA:AQA</em>。</li></ul>',6))])}const D=B(c,[["render",d]]);export{F as __pageData,D as default};
